{
    fill((int*)distance_map, (int*)distance_map + MAX_SIZE * MAX_SIZE, INFINITY);
    distance_map[sr][sc] = 0;
    fill((bool*)reachable, (bool*)reachable + MAX_SIZE * MAX_SIZE, false);
    reachable[sr][sc] = true;
    queue<point> q; q.push(point(sr, sc));
    while (!q.empty()) {
        point v = q.front(); int d = distance_map[v.first][v.second]; q.pop();
        reachable[v.first][v.second] = d <= capacity[v.first][v.second];
        if (d >= capacity[v.first][v.second]) continue;
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            point u = point(v.first + delta_y[dir], v.second + delta_x[dir]);
            if (0 <= u.first && u.first < grid_size && 0 <= u.second && u.second < grid_size && grid[u.first][u.second] != 'Y' && d + 1 < distance_map[u.first][u.second])
                distance_map[u.first][u.second] = d + 1, q.push(u);
        }
    }
}

void run_bfs(int sr, int sc, int dist[][MAX_SIZE], int INF_VAL)
{
    fill((int*)dist, (int*)dist + MAX_SIZE * MAX_SIZE, INF_VAL);
    dist[sr][sc] = 0;
    queue<point> q; q.push(point(sr, sc));
    while (!q.empty()) {
        point v = q.front(); int d_v = dist[v.first][v.second]; q.pop();
        for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
            point u = point(v.first + delta_y[dir], v.second + delta_x[dir]);
            if (0 <= u.first && u.first < grid_size && 0 <= u.second && u.second < grid_size && grid[u.first][u.second] != 'Y' && d_v + 1 < dist[u.first][u.second])
                dist[u.first][u.second] = d_v + 1, q.push(u);
        }
    }
}

int compute_max_flow()
{
    fill(flow_value, flow_value + total_nodes, 0); flow_value[0] = INFINITY;
    priority_queue<point> pq; pq.push(point(INFINITY, 0));
