import java.util.*;
import java.io.*;

public class Main {
    static final int INFINITY = 1000000000;
    static final int MAX_SIZE = 11;
    static final int MAX_NODES = 205;
    static final int DIRECTIONS_COUNT = 4;
    static final int[] delta_y = {-1, 0, 1, 0};
    static final int[] delta_x = {0, -1, 0, 1};

    static int grid_size, time_limit;
    static char[][] grid = new char[MAX_SIZE][MAX_SIZE];
    static char[][] backup = new char[MAX_SIZE][MAX_SIZE];
    static int start_row, start_col;
    static int[][] distance_map = new int[MAX_SIZE][MAX_SIZE];
    static boolean[][] reachable = new boolean[MAX_SIZE][MAX_SIZE];
    static int[][] capacity = new int[MAX_SIZE][MAX_SIZE];
    static List<Integer>[] adj = new ArrayList[MAX_NODES];
    static int[] flow_value = new int[MAX_NODES];
    static int[] parent = new int[MAX_NODES];

    static {
        for (int i = 0; i < MAX_NODES; i++) {
            adj[i] = new ArrayList<>();
        }
    }

    static void first_bfs() {
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(capacity[i], 0);
        }
        capacity[start_row][start_col] = time_limit;
        Queue<Point> q = new LinkedList<>();
        q.offer(new Point(start_row, start_col));
        while (!q.isEmpty()) {
            Point v = q.poll();
            int d = capacity[v.x][v.y];
            for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
                int nx = v.x + delta_y[dir];
                int ny = v.y + delta_x[dir];
                if (0 <= nx && nx < grid_size && 0 <= ny && ny < grid_size && grid[nx][ny] != 'Y' && d + 1 < capacity[nx][ny]) {
                    capacity[nx][ny] = d + 1;
                    q.offer(new Point(nx, ny));
                }
            }
        }
    }

    static void second_bfs(int sr, int sc) {
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(distance_map[i], INFINITY);
            Arrays.fill(reachable[i], false);
        }
        distance_map[sr][sc] = 0;
        reachable[sr][sc] = true;
        Queue<Point> q = new LinkedList<>();
        q.offer(new Point(sr, sc));
        while (!q.isEmpty()) {
            Point v = q.poll();
            int d = distance_map[v.x][v.y];
            reachable[v.x][v.y] = d <= capacity[v.x][v.y];
            if (d >= capacity[v.x][v.y]) continue;
            for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
                int nx = v.x + delta_y[dir];
                int ny = v.y + delta_x[dir];
                if (0 <= nx && nx < grid_size && 0 <= ny && ny < grid_size && grid[nx][ny] != 'Y' && d + 1 < distance_map[nx][ny]) {
                    distance_map[nx][ny] = d + 1;
                    q.offer(new Point(nx, ny));
                }
            }
        }
    }

    static void run_bfs(int sr, int sc, int[][] dist, int INF_VAL) {
        for (int i = 0; i < MAX_SIZE; i++) {
            Arrays.fill(dist[i], INF_VAL);
        }
        dist[sr][sc] = 0;
        Queue<Point> q = new LinkedList<>();
        q.offer(new Point(sr, sc));
        while (!q.isEmpty()) {
            Point v = q.poll();
            int d_v = dist[v.x][v.y];
            for (int dir = 0; dir < DIRECTIONS_COUNT; dir++) {
                int nx = v.x + delta_y[dir];
                int ny = v.y + delta_x[dir];
                if (0 <= nx && nx < grid_size && 0 <= ny && ny < grid_size && grid[nx][ny] != 'Y' && d_v + 1 < dist[nx][ny]) {
                    dist[nx][ny] = d_v + 1;
                    q.offer(new Point(nx, ny));
                }
            }
        }
    }

    static int compute_max_flow(int total_nodes) {
        Arrays.fill(flow_value, 0);
        flow_value[0] = INFINITY;
        PriorityQueue<Point> pq = new PriorityQueue<>((a, b) -> Integer.compare(b.f, a.f));
        pq.offer(new Point(0, 0));
        while (!pq.isEmpty()) {
            Point p = pq.poll();
            int v = p.u;
            int f = p.f;
            if (flow_value[v] != f) continue;
            for (int u : adj[v]) {
                int minCap = Math.min(f, capacity[v][u]);
                if (minCap > flow_value[u]) {
                    flow_value[u] = minCap;
                    parent[u] = v;
                    pq.offer(new Point(u, flow_value[u]));
                }
            }
        }
        int v = total_nodes - 1;
        if (flow_value[v] == 0) return 0;
        int total_flow = flow_value[v];
        while (v != 0) {
            int u = parent[v];
            capacity[u][v] -= total_flow;
            capacity[v][u] += total_flow;
            v = u;
        }
        return total_flow;
    }

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        grid_size = Integer.parseInt(st.nextToken());
        time_limit = Integer.parseInt(st.nextToken());

        for (int i = 0; i < grid_size; i++) {
            String line = br.readLine();
            for (int j = 0; j < grid_size; j++) {
                grid[i][j] = line.charAt(j);
                if (grid[i][j] == 'Z') {
                    start_row = i;
                    start_col = j;
                }
            }
        }

        for (int i = 0; i < grid_size; i++) {
            String line = br.readLine();
            for (int j = 0; j < grid_size; j++) {
                backup[i][j] = line.charAt(j);
            }
        }

        first_bfs();

        int total_nodes = 2 * grid_size * grid_size + 2;

        for (int i = 0; i < grid_size; i++) {
            for (int j = 0; j < grid_size; j++) {
                if (Character.isDigit(grid[i][j]) && grid[i][j] > '0') {
                    int v = i * grid_size + j + 1;
                    capacity[0][v] = grid[i][j] - '0';
                    adj[0].add(v);
                    adj[v].add(0);
                    second_bfs(i, j);
                    for (int i2 = 0; i2 < grid_size; i2++) {
                        for (int j2 = 0; j2 < grid_size; j2++) {
                            if (reachable[i2][j2] && Character.isDigit(backup[i2][j2]) && backup[i2][j2] > '0') {
                                int u = grid_size * grid_size + i2 * grid_size + j2 + 1;
                                capacity[v][u] = INFINITY;
                                adj[v].add(u);
                                adj[u].add(v);
                            }
                        }
                    }
                }
            }
        }

        for (int i = 0; i < grid_size; i++) {
            for (int j = 0; j < grid_size; j++) {
                if (Character.isDigit(backup[i][j]) && backup[i][j] > '0') {
                    int u = grid_size * grid_size + i * grid_size + j + 1;
                    capacity[u][total_nodes - 1] = backup[i][j] - '0';
                    adj[u].add(total_nodes - 1);
                    adj[total_nodes - 1].add(u);
                }
            }
        }

        int total_flow_value = 0;
        int flow;
        while ((flow = compute_max_flow(total_nodes)) != 0) {
            total_flow_value += flow;
        }
        System.out.println(total_flow_value);
    }

    static class Point {
        int x, y, u, f;

        Point(int x, int y) {
            this.x = x;
            this.y = y;
        }

        Point(int u, int f) {
            this.u = u;
            this.f = f;
        }
    }
